WITH RECURSIVE x8 AS (SELECT x7.x3 AS x10 UNION ALL SELECT x7.x3 + 1 FROM x11 WHERE x7.x2 < 10) SELECT x7.x2, x7.x3, ST_ASTEXT(ST_UNION(ST_ENVELOPE(ST_GEOMFROMTEXT('LINESTRING(5 9,-1 10,-2 -6,2 9,2 0,3 6,-3 3,9 -2,-3 -10,-7 -4,1 4)')), ST_UNION(ST_GEOMFROMTEXT('MULTILINESTRING((6 -8,10 -8,3 0,-6 1,0 8,-1 8,-3 -3,6 -6,0 6,1 -6,-1 7,8 3),(-9 -10,-4 0,0 1,-9 1,6 9,-8 7,-2 -6,2 10,-1 -5,3 -5,-1 -10))'), ST_GEOMFROMTEXT('MULTILINESTRING((8 7,2 6,-6 -8,-2 10,4 1,9 7,5 9,4 1,8 2,-2 10,8 -5))')))) AS x4, x7.x2 FROM v226601 AS x7 WHERE x7.x3 BETWEEN SUBTIME('0000-00-00', '00:00:00') AND x7.x3 AND x7.x3 = STR_TO_DATE(DATE_FORMAT(TIME('00:00:00.000000'), CONCAT_WS('-', '%s', '%k')), CONCAT_WS(':', '%i', '%i')) AND x7.x3 BETWEEN UNIX_TIMESTAMP('0000-00-00 00:00:00') AND x7.x2 AND NOT x7.x2 IN (x7.x2, '0000-00-00') AND x7.x3 = 'TABLES'